extern "C" __global__
void depthwise_conv_fp16_kernel(
    const half* __restrict__ input,
    const half* __restrict__ weight,
    const half* __restrict__ bias,
    half* __restrict__ output,
    int batch,
    int channels,
    int height,
    int width,
    int kernel,
    int stride,
    int padding,
    int out_h,
    int out_w)
{
    // One thread per output element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * channels * out_h * out_w;
    if (idx >= total) return;

    // Decompose linear index
    int ow = idx % out_w;
    int tmp = idx / out_w;
    int oh = tmp % out_h;
    tmp = tmp / out_h;
    int c = tmp % channels;
    int n = tmp / channels;

    // Pointers for this batch & channel
    const half* in_ptr  = input  + ((n * channels + c) * height) * width;
    const half* w_ptr   = weight  + (c * kernel * kernel);
    const half* b_ptr   = bias    + c;
    half* out_ptr       = output + ((n * channels + c) * out_h) * out_w;

    float acc = 0.0f;

    // Convolution loop
    for (int ki = 0; ki < kernel; ++ki) {
        int ih = oh * stride - padding + ki;
        if (ih < 0 || ih >= height) continue;
        for (int kj = 0; kj < kernel; ++kj) {
            int iw = ow * stride - padding + kj;
            if (iw < 0 || iw >= width) continue;
            half in_val = in_ptr[ih * width + iw];
            half w_val  = w_ptr[ki * kernel + kj];
            acc += __half2float(in_val) * __half2float(w_val);
        }
    }

    // Add bias if present
    if (bias != nullptr) {
        acc += __half2float(b_ptr[0]);
    }

    out_ptr[oh * out_w + ow] = __float2half(acc);
}
'''

