        # Ensure correct dtype and device
        if x.dtype != torch.float16:
            x = x.to(dtype=torch.float16)
        if not x.is_cuda:
            x = x.cuda()
        return DepthwiseConvFunction.apply(
            x, self.weight, self.bias, self.stride, self.padding
        )

